  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is an increasing body of evidence demonstrating that the accuracy of PoCUS is comparable to the current imaging reference standard CXR in general... However, very few trials have examined meaningful clinical outcomes related to PoCUS usage to date [23] and the results on outcome measurements were heterogeneous [24].",
      "reason": "Describes the current state of knowledge (accuracy comparable to CXR) and important uncertainties (few trials on clinical outcomes, heterogeneous results)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Acute-onset dyspnea is one of the most common symptoms... 30-day mortality rate of these patients remains relatively high... Therefore, rapid and appropriate diagnosis of the underlying pathology is of utmost importance... Therefore, we conducted a high-quality, comprehensive systematic review...",
      "reason": "Explains the importance (high mortality, common symptom) and need for the review (rapid diagnosis important, conventional methods have doubts)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "In addition to the existing diagnostic accuracy studies [16-20, 25], our main objective, as a new insight to this field, was to investigate how PoCUS improves clinical endpoints in patients with acute onset dyspnea.",
      "reason": "Identifies previous reviews (diagnostic accuracy studies) and explains the need for the current review (investigating clinical endpoints)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "PoCUS can answer a broad spectrum of remaining diagnostic questions and may also help to optimize and personalize therapy.",
      "reason": "Briefly describes the proposed mechanism of action (answering diagnostic questions -> optimizing therapy)."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model is presented or described in the manuscript to show hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 90
}

